const ctx = $input.first().json;
const config = $('Config').first().json;

if (!ctx.profile?.id) {
  throw new Error('CONTENT_STUDIO: No business profile returned. Create and approve the profile in admin → Content.');
}
if (ctx.profile.status !== 'approved') {
  throw new Error(`CONTENT_STUDIO: Profile is not approved (status=${ctx.profile.status}).`);
}
if (!Array.isArray(ctx.topics) || ctx.topics.length === 0) {
  throw new Error('CONTENT_STUDIO: No Ready topics. Set at least one topic to Ready in admin → Content.');
}

return [{
  json: {
    ...ctx,
    siteBaseUrl: config.siteBaseUrl,
    openAiModel: config.openAiModel,
  },
}];

const item = $input.first().json;
const today = new Date().toISOString().slice(0, 10);

const dueTopics = item.topics.filter((t) => {
  const d = t.data?.plannedDate;
  return !d || d <= today;
});
const pool = dueTopics.length ? dueTopics : item.topics;

const sorted = [...pool].sort((a, b) => Number(a.data?.priority ?? 99) - Number(b.data?.priority ?? 99));
const topic = sorted[0];
if (!topic?.id) throw new Error('CONTENT_STUDIO: Topic selection failed.');

const titleLower = topic.title.trim().toLowerCase();
const duplicate = (item.existingArticles ?? []).some((a) => a.title?.trim().toLowerCase() === titleLower);
if (duplicate) {
  throw new Error(`CONTENT_STUDIO: Topic title matches an existing article. Rename the topic or archive the article.`);
}

function slugify(raw) {
  const base = raw.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120);
  if (/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(base)) return base;
  return `topic-${topic.id}`.replace(/[^a-z0-9-]/g, '');
}

return [{
  json: {
    siteBaseUrl: item.siteBaseUrl,
    openAiModel: item.openAiModel,
    profile: item.profile,
    sources: item.sources,
    existingArticles: item.existingArticles,
    topic,
    requestKey: `topic-${topic.id}-draft-v1`,
    suggestedSlug: slugify(topic.title),
  },
}];

const row = $input.first().json;
const p = row.profile.data;
const topic = row.topic;

const sourceBlock = (row.sources ?? [])
  .map((s) => `Source id=${s.id}\nURL: ${s.data?.url || ''}\n${s.data?.text || ''}`)
  .join('\n\n---\n\n');

const titles = (row.existingArticles ?? []).map((a) => a.title).join('; ');

const system = [
  'You write editorial drafts for SilentCPO. British English.',
  'Obey profile instructions and exclusions.',
  'Use ONLY facts from approved sources below; never invent statistics, prices, testimonials, or case outcomes.',
  'Return a single JSON object. No markdown fences.',
].join(' ');

const user = [
  '## Profile',
  `Audience: ${p.audience}`,
  `Services: ${p.services}`,
  `Positioning: ${p.positioning}`,
  `Instructions: ${p.instructions}`,
  `Exclusions: ${p.exclusions}`,
  `Competitors (position against these; do not copy; no false claims): ${p.competitors || '(none listed)'}`,
  '',
  '## Approved sources (evidence only)',
  sourceBlock || '(none provided)',
  '',
  '## Topic',
  `Title: ${topic.title}`,
  `Brief: ${topic.data?.brief || ''}`,
  `Keyword: ${topic.data?.keyword || ''}`,
  `Intent: ${topic.data?.intent || ''}`,
  `Rationale: ${topic.data?.rationale || ''}`,
  '',
  '## Existing titles (avoid overlap)',
  titles || '(none)',
  '',
  '## Required JSON keys',
  'title, slug (lowercase a-z0-9 hyphenated), excerpt (<=400 chars), body (markdown with ## headings), metaTitle (<=100), metaDescription (<=200), keyword, sources (private fact-check notes), sourceIds (array of source ids used; empty if none).',
].join('\n');

return [{
  json: {
    ...row,
    openAiBody: {
      model: row.openAiModel,
      response_format: { type: 'json_object' },
      temperature: 0.4,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

const api = $input.first().json;
const row = $('Build OpenAI prompt').first().json;

const content = api.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI: empty response');

let draft;
try {
  draft = JSON.parse(content);
} catch {
  throw new Error('OpenAI: response was not valid JSON');
}

const slugRe = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
if (!draft.title?.trim()) throw new Error('OpenAI: missing title');
if (!draft.slug || !slugRe.test(draft.slug)) draft.slug = row.suggestedSlug;

const sourceIds = Array.isArray(draft.sourceIds) ? draft.sourceIds : [];
const approvedIds = new Set((row.sources ?? []).map((s) => s.id));
for (const id of sourceIds) {
  if (!approvedIds.has(id)) throw new Error(`OpenAI: sourceId ${id} is not an approved source`);
}

const delivery = {
  requestKey: row.requestKey,
  topicId: row.topic.id,
  title: String(draft.title).trim().slice(0, 200),
  slug: draft.slug,
  data: {
    excerpt: String(draft.excerpt ?? '').trim().slice(0, 400),
    body: String(draft.body ?? '').trim().slice(0, 80000),
    metaTitle: String(draft.metaTitle ?? draft.title).trim().slice(0, 100),
    metaDescription: String(draft.metaDescription ?? '').trim().slice(0, 200),
    keyword: String(draft.keyword ?? row.topic.data?.keyword ?? '').trim().slice(0, 500),
    sources: String(draft.sources ?? '').trim().slice(0, 30000),
    sourceIds,
  },
};

return [{
  json: {
    siteBaseUrl: row.siteBaseUrl,
    topicId: row.topic.id,
    topicTitle: row.topic.title,
    delivery,
  },
}];
